CREATE OR REPLACE FUNCTION ECAMS.NODEVCHECKIN 
(SYSCD IN VARCHAR2) 
RETURN VARCHAR2 
IS 
  VCNT  integer := 0; 
BEGIN 
 
     SELECT COUNT(*) 
      INTO VCNT 
      FROM CMM0030 
     WHERE CM_SYSCD=SYSCD 
       AND SUBSTR(CM_SYSINFO,15,1) = 1; 
 
 
    RETURN VCNT; 
 
end;